ROOT=Path(__file__).resolve().parents[1];DOC=ROOT/'docs';D=DOC/'downloads';MINING=ROOT/'data/btc-mining-20261002'
def run():
 rows=[];base=[];annual=[];cost=[];sides=[];ci=[];proof=[];studies={}
 for tag,folder,primary,count in [('MINING','btc-mining-20261002','HG_REC',56),('SHOCK','btc-shock-20261002','SH_REV',40)]:
  R=ROOT/'runs'/folder;s=read(R/'summary.json');v=read(R/'verification.json');rep=read(R/'reproduction.json');sel=read(R/'selection.json');unc=read(R/'uncertainty.json');assert rep['all_bytes_equal'] and v['accounts']==count and not sel['passed'];studies[tag]={'summary':s,'verification':v,'reproduction':rep,'selection':sel,'uncertainty':unc,'information':read(R/('information-age.json' if tag=='MINING' else 'shock-incidence.json'))};diag=read(R/'diagnostics.json') if tag=='MINING' else None
  proof.append([tag,v.get('raw_daily_decisions',v.get('raw_signal_decisions')),v['independent_target_quantities'],v['no_trade_decisions'],v['events'],v['daily_equities'],rep['matched_files']])
  for key,e in s.items():
   p,n,c=key.split('-');m=e['metrics'] if tag=='MINING' else e;dd='max_drawdown_pct' if tag=='MINING' else 'dd_pct';row={'experiment':tag,'strategy':n,'period':p,'scenario':c,'return_pct':m['return_pct'],'max_drawdown_pct':m[dd],**{k:m[k] for k in ('realized_vol_pct','sharpe','round_trips','fees','impact','funding','mean_exposure','max_exposure')}};rows.append(row)
