 evidence={'build':'1002f1','account_rows':rows,'studies':studies,'mining_data_audit':read(MINING/'prepare-audit.json'),'scope':'BTC-only development; mining availability assumptions, not complete original vintages; shocks not confirmed liquidations; author selection and cumulative research selection remain'};(D/'btc-frontier-evidence.json').write_bytes(canonical(evidence))
 with (D/'btc-frontier-summary.csv').open('w',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows(rows)
