  files += [(MINING/name,'mining-data/'+name) for name in read(MINING/'prepare-audit.json')['source_files']];files += [(MINING/n,'mining-data/'+n) for n in ('prepared.json','prepare-audit.json','initial-audit.json','formula-audit.json')]
  for n in ('prepare_btc_mining_data.py','btc_mining_study.py','verify_btc_mining_study.py','test_btc_mining_study.py','reproduce_btc_mining_study.py','btc_shock_study.py','verify_btc_shock_study.py','test_btc_shock_study.py','reproduce_btc_shock_study.py','btc_session_study.py','btc_target_ledger.py','btc_persistence_study.py'):files.append((ROOT/'tools'/n,'source/'+n))
  for p,n in files:z.writestr(zipfile.ZipInfo(n,(2026,10,2,0,0,0)),p.read_bytes())
