 files=['btc-frontier-research.html','btc-web-research.html','downloads/btc-frontier-evidence.zip','downloads/btc-frontier-evidence.json','downloads/btc-frontier-summary.csv','EXPERIMENT_BTC_MINING_20261002.md','EXPERIMENT_BTC_SHOCK_20261002.md','BTC_WEB_RESEARCH_20261002.md','assets/btc-continuation.css','assets/icon.svg'];o=ROOT/'runs/btc-frontier-report-20261002';o.mkdir(exist_ok=True);(o/'public-manifest.json').write_bytes(canonical({n:{'sha256':sha((DOC/n).read_bytes()),'bytes':(DOC/n).stat().st_size} for n in files}));print(json.dumps({'accounts':len(rows),'files':len(files)}))
